#!/usr/bin/env bash
# Builds everything the patched am-hook needs:
#
#   scripts/build.sh /path/to/am-hook [--no-wasm]
#
# 1. builds joc.wasm from joc-wasm/ and installs it as src/ui/joc.wasm,
# 2. installs the HRTF fields from hrtf/ (compiled from the SADIE II database),
# 3. builds the am-hook binary in release mode.
#
# The .jochrtf files are generated by tools/compile_hrtf.py from the public SOFA
# files of the SADIE II database and are redistributed under Apache-2.0.
set -eu
cd "$(dirname "$0")/.."
REPO=$(pwd)
DIR=""
BUILD_WASM=1
while [ $# -gt 0 ]; do
  case "$1" in
    --no-wasm) BUILD_WASM=0; shift ;;
    -*) echo "unknown option $1" >&2; exit 2 ;;
    *) DIR=$1; shift ;;
  esac
done
if [ -z "$DIR" ]; then echo "usage: scripts/build.sh /path/to/am-hook [--no-wasm]" >&2; exit 2; fi
[ -d "$DIR/src/ui" ] || { echo "error: $DIR does not look like an am-hook checkout" >&2; exit 1; }

if [ "$BUILD_WASM" = 1 ]; then
  OUT="$DIR/src/ui/joc.wasm" bash "$REPO/scripts/build-joc-wasm.sh"
else
  echo "keeping the existing src/ui/joc.wasm"
fi

bash "$REPO/scripts/install-hrtf.sh" "$DIR"

cd "$DIR"
cargo build --release
echo
echo "built $(pwd)/target/release/am-hook"
echo "run: $(pwd)/target/release/am-hook --listen 127.0.0.1:8888 --wrapper-url http://127.0.0.1:12340"
